//! 🧺️ Original selected SET children retain every ordered raw reference through bounded copying.
use super::*;
#[derive(semio_framework_value::RetireOwned)]
struct Parts{strings:[Option<String>;7],root:Option<Vec<(String,DslValue)>>,values:Option<Vec<DslValue>>,member:Option<Vec<(String,DslValue)>>,output:Option<DslValue>}
#[derive(Clone,Copy,Default)]
struct State{phase:u8,string:usize,offset:usize,member:usize}
#[derive(Clone,Copy,PartialEq,Eq)]
struct Identity{root:usize,values:usize,length:usize}
pub(super) struct SetCopy{parts:ManuallyDrop<Option<Parts>>,retirement:RetainedCloneClose,state:State,binding:Option<OriginalSourceBinding>,identity:Option<Identity>,closing:bool}
impl Default for SetCopy{fn default()->Self{Self{parts:ManuallyDrop::new(None),retirement:Default::default(),state:Default::default(),binding:None,identity:None,closing:false}}}
fn members(source:&DslValue)->Result<&[DslValue],ValueError>{let DslValue::Object(fields)=source else{return Err(invalid())};if fields.len()!=2||source.get("kind").and_then(DslValue::as_str)!=Some("aggregate"){return Err(invalid());}let Some(DslValue::Array(values))=source.get("value")else{return Err(invalid())};Ok(values)}
fn identity(source:&DslValue)->Result<Identity,ValueError>{let values=members(source)?;Ok(Identity{root:source as*const _ as usize,values:values.as_ptr()as usize,length:values.len()})}
impl SetCopy{
 fn bytes()->usize{4*size_of::<State>()+2*size_of::<Identity>()+2*size_of::<Parts>()+4*size_of::<DslValue>()+4*size_of::<String>()+4*size_of::<Vec<(String,DslValue)>>()}
 fn valid(&self,source:&DslValue)->Result<(),ValueError>{if self.identity.is_some_and(|expected|identity(source).ok()!=Some(expected)){return Err(invalid());}members(source)?;Ok(())}
 fn text<'a>(&self,source:&'a DslValue)->Result<&'a str,ValueError>{Ok(match self.state.string{0|3=>"kind",1=>"aggregate",2|5=>"value",4=>"reference",6=>super::super::super::type_input::reference_text(members(source)?.get(self.state.member).ok_or_else(invalid)?).ok_or_else(invalid)?,_=>return Err(invalid())})}
 pub(super) fn demands(&self,source:&DslValue)->Result<RetirementDemand,ValueError>{self.valid(source)?;let mut demand=RetirementDemand{copy_bytes:Self::bytes(),depth:4,..Default::default()};match self.state.phase{1|6=>demand.capacity_bytes=2*size_of::<(String,DslValue)>(),2=>demand.capacity_bytes=members(source)?.len().checked_mul(size_of::<DslValue>()).ok_or_else(invalid)?,3|7=>demand.capacity_bytes=self.text(source)?.len(),4|8=>demand.copy_bytes=demand.copy_bytes.checked_add(192).ok_or_else(invalid)?,_=>{}}Ok(demand)}
 pub(super) fn advance(&mut self,source:&DslValue,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.valid(source)?;if self.closing||self.binding.is_some_and(|binding|!binding.matches(cx)){return Err(invalid().into());}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"staging SET copy cancelled").into());}let demand=self.demands(source)?;if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),demand){return Ok(false);}if self.state.phase==11{return Ok(true);}let base=Self::bytes();match self.state.phase{
  0=>{*self.parts=Some(Parts{strings:Default::default(),root:None,values:None,member:None,output:None});self.identity=Some(identity(source)?);self.binding=Some(OriginalSourceBinding::borrow(cx));self.state.phase=1;},
  1|6=>{let phase=self.state.phase;let physical=OriginalConstructionDemand{items:1,copy_bytes:base,capacity_bytes:2*size_of::<(String,DslValue)>(),release_bytes:0,depth:4};let parts=self.parts.as_mut().ok_or_else(invalid)?;let target=if phase==1{&mut parts.root}else{&mut parts.member};if admit_original_construction(cx,target,physical,|_|{let mut fields=Vec::new();fields.try_reserve_exact(2).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"SET object backing"))?;let capacity=fields.capacity()*size_of::<(String,DslValue)>();Ok((fields,RetainedCloneProgress{copied_items:1,copied_bytes:base,retained_capacity_bytes:capacity,..Default::default()}))})?{self.state.phase=if phase==1{2}else{7};self.state.string=if phase==1{0}else{3};}return Ok(false);},
  2=>{let count=members(source)?.len();let physical=OriginalConstructionDemand{items:1,copy_bytes:base,capacity_bytes:count.checked_mul(size_of::<DslValue>()).ok_or_else(invalid)?,release_bytes:0,depth:4};if admit_original_construction(cx,&mut self.parts.as_mut().ok_or_else(invalid)?.values,physical,|_|{let mut values=Vec::new();values.try_reserve_exact(count).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"SET member backing"))?;let capacity=values.capacity()*size_of::<DslValue>();Ok((values,RetainedCloneProgress{copied_items:1,copied_bytes:base,retained_capacity_bytes:capacity,..Default::default()}))})?{self.state.phase=3;}return Ok(false);},
  3|7=>{let reserve=self.text(source)?.len();let physical=OriginalConstructionDemand{items:1,copy_bytes:base,capacity_bytes:reserve,release_bytes:0,depth:4};if construct_row_string(&mut self.parts.as_mut().ok_or_else(invalid)?.strings[self.state.string],reserve,"",physical,cx)?{self.state.offset=0;self.state.phase+=1;}return Ok(false);},
  4|8=>{let text=self.text(source)?;let mut end=(self.state.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1;}let chunk=&text[self.state.offset..end];let mut buffer=[0u8;64];buffer[..chunk.len()].copy_from_slice(chunk.as_bytes());self.parts.as_mut().ok_or_else(invalid)?.strings[self.state.string].as_mut().ok_or_else(invalid)?.push_str(std::str::from_utf8(&buffer[..chunk.len()]).expect("UTF8 boundary"));self.state.offset=end;if end==text.len(){self.state.string+=1;self.state.phase=if self.state.phase==4{if self.state.string==3{5}else{3}}else if self.state.string==7{9}else{7};}},
  5=>{if let Some(member)=members(source)?.get(self.state.member){super::super::super::type_input::reference_text(member).ok_or_else(invalid)?;self.state.phase=6;}else{self.state.phase=10;}},
  9=>{let parts=self.parts.as_mut().ok_or_else(invalid)?;if (3..7).any(|index|parts.strings[index].is_none())||parts.member.is_none()||parts.values.is_none(){return Err(invalid().into());}let mut member=parts.member.take().unwrap();member.push((parts.strings[3].take().unwrap(),DslValue::String(parts.strings[4].take().unwrap())));member.push((parts.strings[5].take().unwrap(),DslValue::String(parts.strings[6].take().unwrap())));parts.values.as_mut().unwrap().push(DslValue::Object(member));self.state.member+=1;self.state.phase=5;},
  10=>{let parts=self.parts.as_mut().ok_or_else(invalid)?;if (0..3).any(|index|parts.strings[index].is_none())||parts.root.is_none()||parts.values.is_none(){return Err(invalid().into());}let mut root=parts.root.take().unwrap();root.push((parts.strings[0].take().unwrap(),DslValue::String(parts.strings[1].take().unwrap())));root.push((parts.strings[2].take().unwrap(),DslValue::Array(parts.values.take().unwrap())));parts.output=Some(DslValue::Object(root));self.state.phase=11;},
  _=>return Err(invalid().into()),
 }cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;cx.consume_fuel(1);Ok(self.state.phase==11)}
 pub(super) fn take(&mut self,output:&mut Option<DslValue>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.closing||self.state.phase!=11||output.is_some()||self.binding.is_none_or(|binding|!binding.matches(cx)){return Err(invalid().into());}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"staging SET take cancelled").into());}let demand=RetirementDemand{copy_bytes:Self::bytes(),depth:4,..Default::default()};if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),demand){return Ok(false);}*output=self.parts.as_mut().ok_or_else(invalid)?.output.take();if output.is_none(){return Err(invalid().into());}self.state.phase=12;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
 pub(super) fn begin_close(&mut self){self.closing=true;}
 pub(super) fn empty(&self)->bool{self.parts.is_none()&&self.retirement.is_empty()}
 pub(super) fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.retirement.next_owner_demands::<Parts>(self.parts.is_some(),&None,body)}
 pub(super) fn close_owned(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid());}if !self.retirement.is_empty(){return self.retirement.step_granted(grant);}if self.parts.is_some(){return self.retirement.begin_granted(&mut self.parts,grant)?.ok_or_else(invalid);}Ok(RetainedCloneStep::Complete(Default::default()))}
}
impl RetireOwned for SetCopy{fn retirement(mut self)->Box<dyn RetirementCursor>{self.begin_close();Box::new(self)}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<Self>())}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for SetCopy{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close_demands(body)}fn close_step(&mut self,grant:RetainedCloneGrant)->RetirementStep{match self.close_owned(grant){Ok(RetainedCloneStep::Complete(progress))if progress==Default::default()&&self.empty()=>RetirementStep::Complete,Ok(step)=>RetirementStep::Progress(step.progress()),Err(error)=>RetirementStep::Failure(error)}}fn terminal_is_empty(&self)->bool{self.empty()}fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.copy_bytes)}fn next_selected_work_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.close_demands(body)?.copy_bytes)}fn allows_admitted_narrow_work(&self)->bool{!self.empty()}fn next_birth_bytes(&self,body:usize)->Option<usize>{self.close_demands(body).ok().map(|demand|demand.capacity_bytes)}fn next_close_byte_demand(&self)->Option<usize>{self.close_demands(4096).ok().map(|demand|demand.release_bytes)}fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.depth)}fn terminal_release_bytes(&self)->Option<usize>{self.empty().then_some(size_of::<Self>())}}
impl Drop for SetCopy{fn drop(&mut self){assert!(std::thread::panicking()||self.empty(),"SET copy requires original paid retirement");if self.empty(){unsafe{ManuallyDrop::drop(&mut self.parts);}}}}
#[cfg(test)]
mod tests{
 use super::*;
 use semio_framework_plugin::app_testing::OriginalWorkFixture;
 #[test]
 fn original_set_member_string_survives_refused_receipt_posting(){let mut caller=OriginalWorkFixture::new();let mut copy=Some(SetCopy::default());*copy.as_mut().unwrap().parts=Some(Parts{strings:Default::default(),root:None,values:None,member:None,output:None});let physical=OriginalConstructionDemand{items:1,copy_bytes:4096,capacity_bytes:19,release_bytes:0,depth:4};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|construct_row_string(&mut copy.as_mut().unwrap().parts.as_mut().unwrap().strings[6],20,"original typed draft",physical,cx)));assert!(answer.is_err());assert_eq!(copy.as_ref().unwrap().parts.as_ref().unwrap().strings[6].as_deref(),Some("original typed draft"));assert!(heap.requested_bytes>=20);assert_eq!(heap.released_bytes,0);super::super::set_tests::retire(&mut caller,&mut copy);caller.finish();}
}
